using System.Collections;
using System.Globalization;
using System.Text;
using OcctSharp.CopiedCollections;
using OcctSharp.FoundationValues;
namespace OcctSharp.Runtime.Tests;
#pragma warning disable CA1861 // Fresh arrays deliberately exercise independent copied inputs in each invocation.
public sealed class FoundationDiagnosticTests {
 [Fact]public void SharedFoundationWorkflowFeedsActualModeling()=>OcctSharp.Tests.Shared.BatchAZDiagnosticWorkflow.Run();
 [Fact]public void SymmetricSpectralOutputsReconstructRotatedInputAndRemainIndependent(){
  double[] original={5,4,4,5};var input=new CopiedGrid<double>(original,2,2,-9,13);var result=SdkDiagnostics.SpectralDecomposition(input);Assert.True(result.IsDone);Assert.NotNull(result.Matrix);var v=result.Matrix.ToArray();var d=result.Eigenvalues;
  for(int i=0;i<2;++i)for(int j=0;j<2;++j)Assert.Equal(original[2*i+j],v[2*i]*d[0]*v[2*j]+v[2*i+1]*d[1]*v[2*j+1],10);
  var root=SdkDiagnostics.MatrixSquareRoot(input);Assert.True(root.IsDone);var a=root.Matrix!.ToArray();for(int i=0;i<2;++i)for(int j=0;j<2;++j)Assert.Equal(original[2*i+j],a[2*i]*a[j]+a[2*i+1]*a[2+j],10);
  original[0]=100;Assert.Equal(-9,result.Matrix.RowLower);Assert.Equal(13,result.Matrix.ColumnLower);Assert.Equal(9,d.Max(),10);
 }
 [Fact]public void OptionalMatrixAbsenceNeverPublishesPartialOrNonfiniteValues(){var negative=new CopiedGrid<double>(new[]{-1.0,0,0,4},2,2);var absent=SdkDiagnostics.MatrixSquareRoot(negative);Assert.False(absent.IsDone);Assert.Null(absent.Matrix);Assert.Empty(absent.Eigenvalues);var odd=SdkDiagnostics.MatrixPower(negative,3);Assert.True(odd.IsDone);Assert.Equal(-1,odd.Matrix!.ToArray()[0],10);var singular=SdkDiagnostics.MatrixInverseSquareRoot(new(new[]{0.0,0,0,1},2,2));Assert.False(singular.IsDone);Assert.Null(singular.Matrix);}
 [Fact]public void MatrixPreconditionsRejectAsymmetryNonfiniteAndOversizedBudgets(){Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.MatrixSquareRoot(new(new[]{1.0,2,3,4},2,2)));Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.MatrixPower(new(new[]{double.NaN},1,1),2));Assert.Throws<ArgumentOutOfRangeException>(()=>SdkDiagnostics.MatrixPower(new(new[]{1.0},1,1),double.MaxValue));Assert.Throws<ArgumentException>(()=>SdkDiagnostics.MatrixSquareRoot(new(new double[129*129],129,129)));}
 [Fact]public void PolynomialDerivativeAndResidualAreNumericallyConsistent(){double[] c={-2,0,1};var p=SdkDiagnostics.EvaluatePolynomial(c,3);Assert.Equal(7,p.Value);Assert.Equal(6,p.Derivative);var desc=SdkDiagnostics.EvaluatePolynomial(c.Reverse(),3,true);Assert.Equal(p,desc);var r=SdkDiagnostics.RefinePolynomialRoot(c,1);Assert.InRange(Math.Abs(r.Estimate-Math.Sqrt(2)),0,1e-12);Assert.InRange(Math.Abs(r.Residual),0,1e-12);Assert.Equal(r.Estimate,SdkDiagnostics.RefinePolynomialRoot(c.Reverse(),1,descending:true).Estimate,12);Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.RefinePolynomialRoot(new double[6],1,descending:true));}
 [Fact]public void RootNormalizationCopiesAndInvalidPolynomialArithmeticFails(){double[] roots={3,1,1+1e-12,-2};var copied=SdkDiagnostics.NormalizeRoots(roots);Assert.Equal(new[]{-2.0,1,3},copied);Assert.Equal(3,roots[0]);roots[0]=99;Assert.Equal(3,copied[2]);Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.EvaluatePolynomial(new[]{double.MaxValue,double.MaxValue},double.MaxValue));Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.NormalizeRoots(new[]{1.0},-1));Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.RefinePolynomialRoot(new[]{1.0},0,65));}
 [Theory][InlineData(false)][InlineData(true)]public void QuadratureIntegratesPolynomialAndPublishesIndependentSamples(bool kronrod){var q=kronrod?SdkDiagnostics.KronrodQuadrature(15):SdkDiagnostics.GaussQuadrature(8);Assert.True(q.IsDone);Assert.Equal(2,q.Weights.Sum(),12);Assert.Equal(2.0/5,q.Points.Select((x,i)=>Math.Pow(x,4)*q.Weights[i]).Sum(),12);Assert.All(q.Weights,w=>Assert.True(w>0));Assert.Throws<ArgumentOutOfRangeException>(()=>SdkDiagnostics.KronrodQuadrature(4));Assert.Throws<ArgumentOutOfRangeException>(()=>SdkDiagnostics.GaussQuadrature(62));}
 [Fact]public void MessageMissingTypedParametersHaveExplicitDiagnostics(){var result=SdkDiagnostics.Message("值 %s %d %.2f",new[]{"中文😀"},reals:new[]{2.5});Assert.Equal("值 %s %d %.2f",result.Original);Assert.Equal("值 中文😀 %d 2.50",result.Value);Assert.Equal("值 中文😀 UNKNOWN 2.50",result.Complete);Assert.Equal(1,result.UnresolvedArguments);Assert.True(result.IsEdited);Assert.Equal("",SdkDiagnostics.Message("").Complete);}
 [Fact]public void UnicodePercentAliasCannotIntroduceHiddenSdkFormats(){Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.Message("严d %d",integers:new[]{1}));Assert.Equal("严d",SdkDiagnostics.Message("%s",new[]{"严d"}).Complete);}
 [Theory][InlineData("%100000d")][InlineData("%ld")][InlineData("%n")][InlineData("%*")][InlineData("%.18f")][InlineData("%%")][InlineData("tail%")]
 public void UnsafeMessageFormatsAreRejectedBeforeSdkFormatting(string format)=>Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.Message(format,integers:new[]{1},reals:new[]{1.0}));
 [Fact]public void MessageBudgetsAndUnicodeRejectInvalidInput(){Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.Message("%f",reals:new[]{double.MaxValue}));Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.Message("%s",new[]{"\0"}));Assert.Throws<EncoderFallbackException>(()=>SdkDiagnostics.Message("\ud800"));Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.Message("%d",integers:new[]{1,2}));Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.Message(string.Concat(Enumerable.Repeat("%d",33))));Assert.Equal(int.MinValue.ToString(CultureInfo.InvariantCulture),SdkDiagnostics.Message("%d",integers:new[]{int.MinValue}).Complete);}
 [Fact]public void SetSearchUsesInclusiveUtf16PositionsWithoutSplittingSurrogates(){Assert.Equal(3,SdkDiagnostics.FirstLocationInSet("ab中d","中",1,4));Assert.Equal(3,SdkDiagnostics.FirstLocationInSet("ab中d","ab",1,4,outside:true));Assert.Equal(0,SdkDiagnostics.FirstLocationInSet("abcd","z",1,4,unicode:false));Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.FirstLocationInSet("😀x","x",2,3));Assert.ThrowsAny<Exception>(()=>SdkDiagnostics.FirstLocationInSet("😀x","😀",1,3));}
 [Fact]public void LazyInputBudgetsStopEarlyAndDisposeEnumerators(){var p=new Endless<double>(1);Assert.Throws<ArgumentOutOfRangeException>(()=>SdkDiagnostics.EvaluatePolynomial(p,1));Assert.Equal(258,p.Yielded);Assert.True(p.Disposed);var s=new Endless<string>("x");Assert.Throws<ArgumentOutOfRangeException>(()=>SdkDiagnostics.Message("%s",s));Assert.Equal(33,s.Yielded);Assert.True(s.Disposed);}
 [Fact]public void ConcurrentCopiedMessageAndMatrixCallsDoNotShareReceiverState(){Parallel.For(0,64,i=>{var m=SdkDiagnostics.Message("%d %s",new[]{"文本"},new[]{i});Assert.Equal(i+" 文本",m.Complete);var r=SdkDiagnostics.MatrixPower(new(new[]{2.0,0,0,3},2,2),2);Assert.Equal(new[]{4.0,0,0,9},r.Matrix!.ToArray());});}
 sealed class Endless<T>(T value):IEnumerable<T>{public int Yielded;public bool Disposed;public IEnumerator<T> GetEnumerator(){try{while(true){++Yielded;yield return value;}}finally{Disposed=true;}}IEnumerator IEnumerable.GetEnumerator()=>GetEnumerator();}
}
